package com.himeros.match;import jakarta.persistence.*;import java.time.*;import java.util.*;@Entity@Table(name="matches")class Match{@Id private UUID id;@Column(name="user_a",nullable=false)private UUID userA;@Column(name="user_b",nullable=false)private UUID userB;@Enumerated(EnumType.STRING)@Column(nullable=false)private Status status;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="unmatched_at")private Instant unmatchedAt;enum Status{ACTIVE,UNMATCHED}protected Match(){}Match(UUID a,UUID b){this.id=UUID.randomUUID();if(a.toString().compareTo(b.toString())<0){userA=a;userB=b;}else{userA=b;userB=a;}status=Status.ACTIVE;createdAt=Instant.now();}UUID id(){return id;}UUID a(){return userA;}UUID b(){return userB;}Status status(){return status;}Instant createdAt(){return createdAt;}Instant unmatchedAt(){return unmatchedAt;}void unmatch(){status=Status.UNMATCHED;unmatchedAt=Instant.now();}void reactivate(){status=Status.ACTIVE;unmatchedAt=null;createdAt=Instant.now();}}
